const fs = require('fs');

class Node {
    constructor(char, index, n) {
        this.char = char;
        this.index = index;
        this.nextArray = new Array(26).fill(null);
        this.hasCul = false;
        this.isSame = false;
        this.nextCount = 0;
        this.nextList = [];
        this.countArray = new Array(n).fill(0n);
    }

    addNext(index, node) {
        if (this.nextArray[index] === null) {
            this.nextCount++;
            this.nextArray[index] = node;
            this.nextList.push(node);
        }
    }

    toString() {
        return `${this.char}`;
    }
}

function find(node) {
    if (node.hasCul) {
        return;
    }

    node.countArray[0]++;

    for (const next of node.nextList) {
        find(next);
        for (let i = 0; i < next.countArray.length; i++) {
            if (next.countArray[i] > 0n) {
                node.countArray[i + 1] += next.countArray[i];
            }
        }
    }

    node.hasCul = true;
}

function main() {
    const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);
    let idx = 0;

    const n = parseInt(input[idx++], 10);
    const k = BigInt(input[idx++]);
    const str = input[idx++];

    const letters = new Array(26).fill(false);
    const list = [];

    for (let i = 0; i < str.length; i++) {
        const char = str[i];
        const node = new Node(char, i, n);
        const ci = char.charCodeAt(0) - 'a'.charCodeAt(0);
        if (letters[ci]) {
            node.isSame = true;
        } else {
            letters[ci] = true;
        }
        list.push(node);
    }

    for (let i = 0; i < list.length; i++) {
        const ai = list[i];
        for (let j = i + 1; j < list.length; j++) {
            const aj = list[j];
            const idxChar = aj.char.charCodeAt(0) - 'a'.charCodeAt(0);
            ai.addNext(idxChar, aj);
        }
    }

    for (const node of list) {
        find(node);
    }

    const totalCountArray = new Array(n).fill(0n);
    for (let i = 0; i < n; i++) {
        for (const node of list) {
            if (!node.isSame) {
                totalCountArray[i] += node.countArray[i];
            }
        }
    }

    let totalCost = 0n;
    let selectCount = 0n;

    for (let i = n - 1; i >= 0; i--) {
        const cnt = totalCountArray[i];
        if (selectCount + cnt < k) {
            totalCost += BigInt((n - 1 - i)) * cnt;
            selectCount += cnt;
        } else {
            const over = (selectCount + cnt) - k;
            totalCost += BigInt((n - 1 - i)) * (cnt - over);
            selectCount += (cnt - over);
            break;
